const express = require('express');
const crypto = require('crypto');
const app = express();

// In-memory user store
const users = new Map();
const sessions = new Map();

// Deep merge utility for user preferences
function deepMerge(target, source) {
  if (!source || typeof source !== 'object') return target;
  if (Array.isArray(source)) return [...source];

  const result = { ...target };
  for (const key of Object.keys(source)) {
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') continue;
    const val = source[key];
    if (val !== null && typeof val === 'object' && !Array.isArray(val)) {
      result[key] = deepMerge(result[key] || {}, val);
    } else {
      result[key] = val;
    }
  }
  return result;
}

// Sanitize user input - blocks dangerous keys recursively
function sanitizeInput(obj) {
  if (typeof obj !== 'object' || obj === null) return obj;
  const cleaned = {};
  for (const [key, value] of Object.entries(obj)) {
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') continue;
    if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
      cleaned[key] = sanitizeInput(value);
    } else {
      cleaned[key] = value;
    }
  }
  return cleaned;
}

app.use(express.json({ limit: '1mb' }));

// Register endpoint
app.post('/api/register', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }
  if (username.length > 64 || password.length > 128) {
    return res.status(400).json({ error: 'Input too long' });
  }
  if (users.has(username)) {
    return res.status(409).json({ error: 'User exists' });
  }

  const salt = crypto.randomBytes(16).toString('hex');
  const hash = crypto.scryptSync(password, salt, 64).toString('hex');
  users.set(username, { hash, salt, role: 'user', preferences: {} });
  res.json({ success: true });
});

// Login endpoint
app.post('/api/login', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }
  const user = users.get(username);
  if (!user) return res.status(401).json({ error: 'Invalid credentials' });

  const hash = crypto.scryptSync(password, user.salt, 64).toString('hex');
  if (!crypto.timingSafeEqual(Buffer.from(hash), Buffer.from(user.hash))) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = crypto.randomBytes(32).toString('hex');
  sessions.set(token, { username, created: Date.now() });
  res.json({ token });
});

// Middleware to check auth
function authenticate(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token || typeof token !== 'string') return res.status(401).json({ error: 'No token' });
  const session = sessions.get(token);
  if (!session) return res.status(401).json({ error: 'Invalid session' });
  if (Date.now() - session.created > 3600000) {
    sessions.delete(token);
    return res.status(401).json({ error: 'Session expired' });
  }
  req.user = users.get(session.username);
  req.username = session.username;
  next();
}

// Update user preferences - applies sanitization then deep merge
app.put('/api/preferences', authenticate, (req, res) => {
  const input = sanitizeInput(req.body);
  const user = req.user;

  // Deep merge preferences with existing ones
  user.preferences = deepMerge(user.preferences, input);
  res.json({ preferences: user.preferences });
});

// Admin endpoint
app.get('/api/admin/users', authenticate, (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }
  const userList = [];
  for (const [username, data] of users.entries()) {
    userList.push({ username, role: data.role });
  }
  res.json({ users: userList });
});

// Check if current user is admin
app.get('/api/whoami', authenticate, (req, res) => {
  res.json({ username: req.username, role: req.user.role, isAdmin: req.user.role === 'admin' });
});

app.listen(3000);
module.exports = app;
